sys_variable_value.value:
(function execute(inputs, outputs) {
    var gr_attachment = new GlideRecord("sys_attachment");
    gr_attachment.addQuery("table_sys_id", inputs.gr_data_source.getValue("sys_id"));
    gr_attachment.orderBy("sys_created_on");
    gr_attachment.setLimit(1);
    gr_attachment.query();
    gr_attachment.next();
    outputs.gr_attachment = gr_attachment;
})(inputs, outputs);

